/// <summary>
/// CB223_PalletRounding
/// Post pricing order optimisation multithread batch task
/// inspired from new class LedgerJournalBatchPost
/// </summary>
class METSalesOrderCreditMgmtCheckService extends METSysOperationService
{
    private guid topPickingProcessId;
    container    salesOrderCon = conNull();
    str          menuItemName;

}

Method.Source:
/// <summary>
/// Returns task service class name.
/// </summary>
/// <returns>Task service class name</returns>
protected str getTaskServiceClass()
{
    return classStr(METSalesOrderCreditMgmtCheckTaskService);
}

/// <summary>
/// Returns task service class method.
/// </summary>
/// <returns>Task service class method</returns>
protected str getTaskServiceClassMethod()
{
    return methodStr(METSalesOrderCreditMgmtCheckTaskService, process);
}

/// <summary>
/// Returns caption of the task service class.
/// </summary>
/// <returns>Task service class caption</returns>
protected str getTaskServiceCaption()
{
    return "@MET:PostPricingOrderOptimisation";
}

/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METSysOperationTaskDataContract</c>
/// </param>
public void process(METSalesOrderCreditMgmtCheckContract _contract)
{
    menuItemName  = _contract.parmMenuItemName();
    salesOrderCon = _contract.parmSalesOrderCon();
    this.processInternal(_contract);
}

/// <summary>Initialise global variables</summary>
public void initialise()
{
    super();

    METSalesOrderCreditMgmtCheckContract contract = dataContract as METSalesOrderCreditMgmtCheckContract;
    Query query = contract.getQuery();

    this.processSalesOrders(query);

}

/// <summary>
/// Initializes the task data contract.
/// </summary>
/// <param name = "_taskDataContract">task data contract</param>
protected void initTaskDataContract(METSysOperationTaskDataContract _taskDataContract)
{
    super(_taskDataContract);
    METSalesOrderCreditMgmtCheckContract contract = _taskDataContract as METSalesOrderCreditMgmtCheckContract;
    contract.parmTopPickingProcessId(topPickingProcessId);
}

/// <summary>
/// Provides task data contract.
/// </summary>
/// <returns>task data contract</returns>
protected METSysOperationTaskDataContract taskDataContractObject()
{
    return new METSalesOrderCreditMgmtCheckContract();
}

/// <summary>
/// Process sales orders to pallet rounding and quotas from the query and insert SO number in <c>METSalesOrderCreditMgmtCheckQueue</c>
/// </summary>
/// <param name = "_query"><c>Query</c> object</param>
void processSalesOrders(Query _query)
{
    SalesTable st;
    RecordInsertList soCreditMgmtCheckQueueList;
    #OCCRetryCount

    METSalesOrderCreditMgmtCheckQueue::cleanUpPostSalesOrderCreationProcessingQueue();
    soCreditMgmtCheckQueueList = new RecordInsertList(tableNum(METSalesOrderCreditMgmtCheckQueue));
    topPickingProcessId = newGuid();

    // Check the caller from Pricing optimisation batch job.
    if(menuItemName == menuItemActionStr(METPostPricingOrderOptimisationController))
    {
        for(int i=1; i<=conLen(salesOrderCon); i++)
        {
            this.processSingleSalesOrder(soCreditMgmtCheckQueueList, conPeek(salesOrderCon, i));
        }
    }
    else
    {
        QueryRun qr = new QueryRun(_query);

        while (qr.next())
        {
            st = qr.get(tableNum(SalesTable));

            this.processSingleSalesOrder(soCreditMgmtCheckQueueList, st.SalesId);
        }
    }
    this.insertIntoTopPickingQueue(soCreditMgmtCheckQueueList);
}

/// <summary>
/// Adding sales order to process into the RecordInsertList
/// </summary>
/// <param name = "_journalPostQueueList"><c>RecordInsertList</c> object</param>
/// <param name = "_salesId">Sales order number</param>
private void addToPostPricingOrderOptimisationQueueList(RecordInsertList _journalPostQueueList, SalesIdBase _salesId)
{
    METSalesOrderCreditMgmtCheckQueue postRecord;
    postRecord.ProcessId = this.topPickingProcessId;
    postRecord.SalesId = _salesId;

    _journalPostQueueList.add(postRecord);
}

/// <summary>
/// Buld insert from RecordInsertList into <c>METSalesOrderCreditMgmtCheckQueue</c>
/// </summary>
/// <param name = "_postPricingOrderOptimisationQueueList">RecordInsertList to bulk insert</param>
private void insertIntoTopPickingQueue(RecordInsertList _postPricingOrderOptimisationQueueList)
{
    _postPricingOrderOptimisationQueueList.insertDatabase();
}

/// <summary>
/// Adding sales order to list
/// </summary>
/// <param name = "soCreditMgmtCheckQueueList">List of sales orders queue</param>
/// <param name = "_salesId">salesid</param>
private void processSingleSalesOrder(RecordInsertList soCreditMgmtCheckQueueList, SalesId _salesId)
{
    #define.RetryNum(5);

    try
    {
        this.addToPostPricingOrderOptimisationQueueList(soCreditMgmtCheckQueueList, _salesId);
    }
    catch (Exception::Deadlock)
    {
        if (xSession::currentRetryCount() >= #RetryNum)
        {
            throw Exception::Deadlock;
        }
        else
        {
            retry;
        }
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
    catch (Exception::Error)
    {
        // catch the errors so processing can continue
        curext(); // avoids a warning about an empty block
    }
}
